contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address caller, address newOwner) public payable {
        require(caller != address(0));
        require(newOwner != address(0));

        // The deployer/constructor caller becomes the initial owner.
        address initialOwner = c.owner();
        require(initialOwner == msg.sender);

        address newOwnerParam = newOwner;
        bool callerIsOwner = (caller == initialOwner);
        address callerAddr = caller;

        bool reverted;
        if (callerIsOwner) {
            // Top-level state-changing call from the owner.
            c.transferOwnership(newOwnerParam);
            reverted = false;
        } else {
            // Top-level state-changing call from a non-owner; should revert.
            callerAddr = caller;
            try c.transferOwnership(newOwnerParam) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        assert(
            (!callerIsOwner && reverted && c.owner() == initialOwner) ||
            (callerIsOwner && !reverted && c.owner() == newOwnerParam)
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

