    }

    function run(address newOwner) public payable {
        require(newOwner != address(0));

        // The deployer (this test contract) is the initial owner.
        address initialOwner = c.owner();
        require(initialOwner == msg.sender);

        // This call is made by the owner and must succeed, changing ownership.
        c.transferOwnership(newOwner);

        // Record the state after the owner's successful transfer.
        bool ownerChanged = (c.owner() == newOwner);

        // Non-owner call must revert; use try/catch at top level as required.
        bool nonOwnerReverted;
        try c.transferOwnership(address(0xdead)) {
            nonOwnerReverted = false;
        } catch {
            nonOwnerReverted = true;
        }

        assert(ownerChanged && nonOwnerReverted && c.owner() == newOwner);
    }

    receive() external payable {}
}

