    }

    function run(address caller, address newOwner) public payable {
        require(newOwner != address(0));

        address initialOwner = c.owner();
        require(initialOwner != address(0));

        if (caller != initialOwner) {
            // caller is not the owner: the call must revert and leave owner unchanged
            bool reverted;
            try c.transferOwnership(newOwner) {
                reverted = false;
            } catch {
                reverted = true;
            }
            address afterOwner = c.owner();
            assert(reverted && afterOwner == initialOwner);
