            // caller is the owner: the call must succeed and update owner
            bool reverted;
            try c.transferOwnership(newOwner) {
                reverted = false;
            } catch {
                reverted = true;
            }
            address afterOwner = c.owner();
            assert(!reverted && afterOwner == newOwner);
        }
    }

